<?php
declare(strict_types=1);namespace App\Service;
use App\Exception\AuthException;use Hyperf\Contract\IdGeneratorInterface;use Hyperf\Database\ConnectionInterface;use Hyperf\DbConnection\Db;
final class BillingService
{
 public function __construct(private Db$db,private IdGeneratorInterface$ids){}
 /** @return list<array<string,mixed>> */public function buyerInvoices(int$id):array{return$this->rows($this->db->select('SELECT `id`,`period_id`,`status`,`total_micros`,`due_at`,`grace_until`,`paid_at` FROM `billing_invoices` WHERE `buyer_profile_id`=? AND `deleted_at` IS NULL ORDER BY `period_id` DESC',[$id]));}
 /** @return list<array<string,mixed>> */public function supplierSettlements(int$id):array{return$this->rows($this->db->select('SELECT `id`,`period_id`,`gross_micros`,`commission_micros`,`net_micros`,`status`,`confirmed_at` FROM `supplier_settlements` WHERE `supplier_profile_id`=? AND `deleted_at` IS NULL ORDER BY `period_id` DESC',[$id]));}
 /** @return list<array<string,mixed>> */public function pendingProofs():array{return$this->rows($this->db->select('SELECT `id`,`invoice_id`,`reference_no`,`proof_path`,`created_at` FROM `payment_proofs` WHERE `status`=\'pending\' AND `deleted_at` IS NULL ORDER BY `created_at`'));}
 public function submitProof(int$buyer,int$invoice,string$reference,string$path):void{$reference=trim($reference);$path=trim($path);if($reference===''||mb_strlen($reference)>128||$path===''||mb_strlen($path)>512)throw AuthException::badRequest('付款凭证字段无效。');$this->db->transaction(function(ConnectionInterface$c)use($buyer,$invoice,$reference,$path):void{if($c->selectOne('SELECT `id` FROM `billing_invoices` WHERE `id`=? AND `buyer_profile_id`=? AND `status` IN (\'issued\',\'overdue\') AND `deleted_at` IS NULL LIMIT 1 FOR UPDATE',[$invoice,$buyer])===null)throw AuthException::badRequest('账单不可提交凭证。');$c->insert('INSERT INTO `payment_proofs` (`id`,`invoice_id`,`reference_no`,`proof_path`,`status`,`reviewed_by_admin_id`,`reviewed_at`,`created_at`,`updated_at`,`deleted_at`) VALUES (?,?,?,?,\'pending\',NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL)',[$this->ids->generate(),$invoice,$reference,$path]);$c->update('UPDATE `billing_invoices` SET `status`=\'proof_pending\',`updated_at`=CURRENT_TIMESTAMP WHERE `id`=?',[$invoice]);});}
 public function confirmPayment(int$admin,int$proof):void{$this->db->transaction(function(ConnectionInterface$c)use($admin,$proof):void{$p=$c->selectOne('SELECT `id`,`invoice_id`,`status` FROM `payment_proofs` WHERE `id`=? AND `deleted_at` IS NULL LIMIT 1 FOR UPDATE',[$proof]);if(!is_object($p)||(string)$p->status!=='pending')throw AuthException::badRequest('待确认凭证不存在。');$c->update('UPDATE `payment_proofs` SET `status`=\'confirmed\',`reviewed_by_admin_id`=?,`reviewed_at`=CURRENT_TIMESTAMP,`updated_at`=CURRENT_TIMESTAMP WHERE `id`=?',[$admin,$proof]);$c->update('UPDATE `billing_invoices` SET `status`=\'paid\',`paid_at`=CURRENT_TIMESTAMP,`updated_at`=CURRENT_TIMESTAMP WHERE `id`=?',[(int)$p->invoice_id]);$c->update('UPDATE `api_subscriptions` s INNER JOIN `billing_items` i ON i.`subscription_id`=s.`id` SET s.`status`=\'active\',s.`updated_at`=CURRENT_TIMESTAMP WHERE i.`invoice_id`=? AND s.`status`=\'billing_suspended\'',[(int)$p->invoice_id]);$this->audit($c,$admin,'payment_confirmed','payment_proof',$proof,['invoice_id'=>(int)$p->invoice_id]);});}
 public function pauseOverdue():void{$this->db->transaction(function(ConnectionInterface$c):void{foreach($c->select('SELECT `id` FROM `billing_invoices` WHERE `status` IN (\'issued\',\'proof_pending\') AND `grace_until`<CURRENT_TIMESTAMP AND `deleted_at` IS NULL FOR UPDATE')as$r){$id=(int)(is_object($r)?$r->id:$r['id']);$c->update('UPDATE `billing_invoices` SET `status`=\'overdue\',`updated_at`=CURRENT_TIMESTAMP WHERE `id`=?',[$id]);$c->update('UPDATE `api_subscriptions` s INNER JOIN `billing_items` i ON i.`subscription_id`=s.`id` SET s.`status`=\'billing_suspended\',s.`updated_at`=CURRENT_TIMESTAMP WHERE i.`invoice_id`=? AND s.`status`=\'active\'',[$id]);$this->audit($c,null,'invoice_overdue','invoice',$id,[]);}});}
 public function setCommission(int$admin,int$supplier,int$bps):void{if($bps<0||$bps>10000)throw AuthException::badRequest('佣金率无效。');$this->db->transaction(function(ConnectionInterface$c)use($admin,$supplier,$bps):void{$c->update('UPDATE `commission_configs` SET `status`=\'inactive\',`updated_at`=CURRENT_TIMESTAMP WHERE `supplier_profile_id`=? AND `status`=\'active\' AND `deleted_at` IS NULL',[$supplier]);$id=$this->ids->generate();$c->insert('INSERT INTO `commission_configs` (`id`,`supplier_profile_id`,`commission_bps`,`status`,`effective_at`,`created_at`,`updated_at`,`deleted_at`) VALUES (?,?,?,\'active\',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL)',[$id,$supplier,$bps]);$this->audit($c,$admin,'commission_changed','commission_config',$id,['supplier_profile_id'=>$supplier,'commission_bps'=>$bps]);});}
 public function confirmSettlement(int$admin,int$id):void{$this->db->transaction(function(ConnectionInterface$c)use($admin,$id):void{if($c->update('UPDATE `supplier_settlements` SET `status`=\'confirmed\',`confirmed_by_admin_id`=?,`confirmed_at`=CURRENT_TIMESTAMP,`updated_at`=CURRENT_TIMESTAMP WHERE `id`=? AND `status`=\'pending\' AND `deleted_at` IS NULL',[$admin,$id])!==1)throw AuthException::badRequest('待确认结算单不存在。');$this->audit($c,$admin,'settlement_confirmed','settlement',$id,[]);});}
 public function generatePeriod(string$period,int$dueDays=7,int$graceDays=3):void{if(preg_match('/^[0-9]{4}-[0-9]{2}$/D',$period)!==1)throw AuthException::badRequest('账期无效。');$this->db->transaction(function(ConnectionInterface$c)use($period,$dueDays,$graceDays):void{$lock='uniapi:billing:'.$period;$got=$c->selectOne('SELECT GET_LOCK(?,0) AS `acquired`',[$lock]);if(!is_object($got)||(int)$got->acquired!==1)throw AuthException::conflict('账期正在生成。');try{$rows=$this->rows($c->select('SELECT a.`buyer_profile_id`,s.`id` AS `subscription_id`,s.`supplier_profile_id`,u.`call_count`,p.`unit_price_micros`,COALESCE((SELECT `commission_bps` FROM `commission_configs` cc WHERE cc.`supplier_profile_id`=s.`supplier_profile_id` AND cc.`status`=\'active\' AND cc.`deleted_at` IS NULL ORDER BY cc.`effective_at` DESC LIMIT 1),0) AS `commission_bps` FROM `usage_aggregates` u INNER JOIN `api_subscriptions` s ON s.`id`=u.`subscription_id` INNER JOIN `buyer_applications` a ON a.`id`=s.`application_id` INNER JOIN `api_prices` p ON p.`api_version_id`=s.`api_version_id` AND p.`deleted_at` IS NULL WHERE u.`period_id`=? AND u.`deleted_at` IS NULL',[$period]));$buyers=[];$suppliers=[];foreach($rows as$r){$gross=$this->multiply((int)$r['call_count'],(int)$r['unit_price_micros']);$commission=$this->bps($gross,(int)$r['commission_bps']);$r+=['gross_micros'=>$gross,'commission_micros'=>$commission,'supplier_net_micros'=>$gross-$commission];$buyers[(int)$r['buyer_profile_id']][]=$r;$sid=(int)$r['supplier_profile_id'];$suppliers[$sid]=[($suppliers[$sid][0]??0)+$gross,($suppliers[$sid][1]??0)+$commission];}foreach($buyers as$buyer=>$items){if($c->selectOne('SELECT `id` FROM `billing_invoices` WHERE `buyer_profile_id`=? AND `period_id`=? LIMIT 1 FOR UPDATE',[$buyer,$period])!==null)continue;$invoice=$this->ids->generate();$total=array_sum(array_column($items,'gross_micros'));$c->insert('INSERT INTO `billing_invoices` (`id`,`buyer_profile_id`,`period_id`,`status`,`total_micros`,`issued_at`,`due_at`,`grace_until`,`paid_at`,`created_at`,`updated_at`,`deleted_at`) VALUES (?,?,?,\'issued\',?,CURRENT_TIMESTAMP,DATE_ADD(CURRENT_TIMESTAMP,INTERVAL ? DAY),DATE_ADD(CURRENT_TIMESTAMP,INTERVAL ? DAY),NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL)',[$invoice,$buyer,$period,$total,$dueDays,$dueDays+$graceDays]);foreach($items as$i)$c->insert('INSERT INTO `billing_items` (`id`,`invoice_id`,`subscription_id`,`supplier_profile_id`,`call_count`,`unit_price_micros`,`gross_micros`,`commission_bps`,`commission_micros`,`supplier_net_micros`,`created_at`,`updated_at`,`deleted_at`) VALUES (?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL)',[$this->ids->generate(),$invoice,$i['subscription_id'],$i['supplier_profile_id'],$i['call_count'],$i['unit_price_micros'],$i['gross_micros'],$i['commission_bps'],$i['commission_micros'],$i['supplier_net_micros']]);}foreach($suppliers as$supplier=>$sum)$c->insert('INSERT IGNORE INTO `supplier_settlements` (`id`,`supplier_profile_id`,`period_id`,`gross_micros`,`commission_micros`,`net_micros`,`status`,`confirmed_by_admin_id`,`confirmed_at`,`created_at`,`updated_at`,`deleted_at`) VALUES (?,?,?,?,?,?,\'pending\',NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL)',[$this->ids->generate(),$supplier,$period,$sum[0],$sum[1],$sum[0]-$sum[1]]);}finally{$c->selectOne('SELECT RELEASE_LOCK(?) AS `released`',[$lock]);}});}
 private function multiply(int$a,int$b):int{if($a<0||$b<0||($b!==0&&$a>intdiv(PHP_INT_MAX,$b)))throw AuthException::badRequest('账单金额超出范围。');return$a*$b;}private function bps(int$g,int$b):int{return intdiv($g,10000)*$b+intdiv(($g%10000)*$b,10000);}/** @param list<object|array<string,mixed>>$r @return list<array<string,mixed>> */private function rows(array$r):array{return array_map(static fn(object|array$v):array=>is_object($v)?get_object_vars($v):$v,$r);}private function audit(ConnectionInterface$c,?int$a,string$action,string$type,int$id,array$summary):void{$c->insert('INSERT INTO `billing_audit_logs` (`id`,`actor_admin_id`,`action`,`target_type`,`target_id`,`summary`,`created_at`,`updated_at`,`deleted_at`) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL)',[$this->ids->generate(),$a,$action,$type,$id,json_encode($summary,JSON_THROW_ON_ERROR)]);}
}
